CREATE TEXT SEARCH DICTIONARY ispell (Template = ispell, DictFile = ispell_sample, AffFile = ispell_sample);
CREATE TEXT SEARCH DICTIONARY hunspell (Template = ispell, DictFile = ispell_sample, AffFile = hunspell_sample);
CREATE TEXT SEARCH DICTIONARY hunspell_long (Template = ispell, DictFile = hunspell_sample_long, AffFile = hunspell_sample_long);
CREATE TEXT SEARCH DICTIONARY hunspell_num (Template = ispell, DictFile = hunspell_sample_num, AffFile = hunspell_sample_num);
CREATE TEXT SEARCH DICTIONARY ispell_stop (Template = ispell, DictFile = ispell_sample, AffFile = ispell_sample, StopWords = english);
SELECT d.n AS dict, w.n AS word, ts_lexize(d.d::regdictionary, w.w) FROM unnest(array['ispell', 'hunspell', 'hunspell_long', 'hunspell_num']) WITH ORDINALITY d(d, n), unnest(array['skies', 'sky', 'bookings', 'booking', 'foot', 'foots', 'rebookings', 'rebooking', 'rebook', 'unbookings', 'unbooking', 'unbook', 'booked', 'footklubber', 'footballklubber', 'ballyklubber', 'footballyklubber', 'ex-machina', 'machina', 'ex-', 'book', 'books', 'Booking', 'balls', 'bally', 'klubber', 'footballs', 'footballklubbers', 'ballklubber', 'footfoot', 'footballfootball', 'balllyklubber', 'xyz', '', 'skied', 'skys']) WITH ORDINALITY w(w, n) ORDER BY 1, 2;
SELECT ts_lexize('ispell_stop', 'the'), ts_lexize('ispell_stop', 'booking');
CREATE TEXT SEARCH CONFIGURATION ispell_tst (COPY = english);
ALTER TEXT SEARCH CONFIGURATION ispell_tst ALTER MAPPING FOR word, numword, asciiword, hword, numhword, asciihword, hword_part, hword_numpart, hword_asciipart WITH ispell, english_stem;
SELECT to_tsvector('ispell_tst', 'Booking the skies after rebookings for footballklubber from a foot');
SELECT to_tsquery('ispell_tst', 'footballklubber');
SELECT to_tsquery('ispell_tst', 'footballyklubber:b & rebookings:A & sky');
SELECT to_tsquery('ispell_tst', 'footballyklubber:b <-> sky');
SELECT phraseto_tsquery('ispell_tst', 'footballyklubber sky');
SELECT ts_debug('ispell_tst', 'footballklubber skies');
CREATE TEXT SEARCH CONFIGURATION hunspell_tst (COPY = ispell_tst);
ALTER TEXT SEARCH CONFIGURATION hunspell_tst ALTER MAPPING REPLACE ispell WITH hunspell;
SELECT to_tsvector('hunspell_tst', 'Booking the skies after rebookings for footballklubber from a foot');
SELECT to_tsquery('hunspell_tst', 'footballyklubber:b & rebookings:A & sky');
ALTER TEXT SEARCH CONFIGURATION hunspell_tst ALTER MAPPING REPLACE hunspell WITH hunspell_long;
SELECT to_tsvector('hunspell_tst', 'Booking the skies after rebookings for footballklubber from a foot ex-machina');
ALTER TEXT SEARCH CONFIGURATION hunspell_tst ALTER MAPPING REPLACE hunspell_long WITH hunspell_num;
SELECT to_tsvector('hunspell_tst', 'Booking the skies after rebookings for footballklubber from a foot booked');
SELECT ts_headline('hunspell_tst', 'Booking the skies after rebookings for footballklubber from a foot', to_tsquery('hunspell_tst', 'book & sky'));
CREATE TEXT SEARCH DICTIONARY hunspell_invalid_1 (Template = ispell, DictFile = hunspell_sample_long, AffFile = ispell_sample);
CREATE TEXT SEARCH DICTIONARY hunspell_invalid_2 (Template = ispell, DictFile = hunspell_sample_long, AffFile = hunspell_sample_num);
CREATE TEXT SEARCH DICTIONARY hunspell_invalid_3 (Template = ispell, DictFile = hunspell_sample_num, AffFile = ispell_sample);
CREATE TEXT SEARCH DICTIONARY hunspell_err (Template = ispell, DictFile = hunspell_sample_num, AffFile = hunspell_sample_long);
CREATE TEXT SEARCH DICTIONARY hunspell_invalid_4 (Template = ispell, DictFile = hunspell_sample_long, AffFile = hunspell_sample_long);
SELECT ts_lexize('hunspell_invalid_1', 'book'), ts_lexize('hunspell_invalid_3', 'book');
CREATE TEXT SEARCH DICTIONARY bad (Template = ispell, DictFile = ispell_sample);
CREATE TEXT SEARCH DICTIONARY bad (Template = ispell, AffFile = ispell_sample);
CREATE TEXT SEARCH DICTIONARY bad (Template = ispell, DictFile = nosuch, AffFile = ispell_sample);
CREATE TEXT SEARCH DICTIONARY bad (Template = ispell, DictFile = ispell_sample, AffFile = nosuch);
CREATE TEXT SEARCH DICTIONARY bad (Template = ispell, DictFile = ispell_sample, AffFile = ispell_sample, AffFile = ispell_sample);
CREATE TEXT SEARCH DICTIONARY bad (Template = ispell, DictFile = ispell_sample, AffFile = ispell_sample, foo = bar);
CREATE TEXT SEARCH DICTIONARY bad (Template = ispell, DictFile = english, AffFile = ispell_sample);
